import math

def calculate_s(n, p, q):
    # S = (12 + n) / p + (13 - n) / q
    try:
        s = (12 + n) / p + (13 - n) / q
        return s, (n, p, q)
    except ZeroDivisionError:
        return -1, (n, p, q)

max_s = 0.0
best_config = None

# Search p and q up to 200 with |p - q| <= 5
for p in range(1, 201):
    for q in range(max(1, p - 5), min(201, p + 6)):
        if p == 0 or q == 0:
            continue

        # Optimize n for this (p, q) pair
        # S is linear in n: S = (12/p + 13/q) + n * (1/p - 1/q)

        if p == q:
            # This case is excluded by |p-q| <= 5 and 'not consecutive' phrasing,
            # but we check it anyway if the interpretation allows p=q. 
            # Since the prompt says "not consecutive", we assume p != q.
            pass 

        # Derivative with respect to n: dS/dn = 1/p - 1/q

        # If 1/p - 1/q > 0 (i.e., p < q), S increases with n. Optimal n = 12.
        if p < q:
            n_opt = 12
        # If 1/p - 1/q < 0 (i.e., p > q), S decreases with n. Optimal n = 1.
        elif p > q:
            n_opt = 1
        else: # p = q, slope is 0. Max S is constant for all n.
            n_opt = 12 # Arbitrarily choose 12 if we include p=q

        # Check the optimal n
        s, config = calculate_s(n_opt, p, q)

        # Check boundary cases for n just in case the optimum is outside [1, 12]
        s1, _ = calculate_s(1, p, q)
        s12, _ = calculate_s(12, p, q)

        current_max_s = 0.0

        # Check the chosen n_opt, and the endpoints n=1 and n=12
        candidates_s = [s]
        if n_opt != 1:
            candidates_s.append(s1)
        if n_opt != 12:
            candidates_s.append(s12)

        for s_candidate in candidates_s:
            if s_candidate < 1.0 and s_candidate > current_max_s:
                current_max_s = s_candidate

        if current_max_s > max_s:
            max_s = current_max_s
            best_config = (p, q, n_opt if current_max_s == s else (1 if current_max_s == s1 else 12))

print(f"Maximum S found: {max_s}")
print(f"Best Configuration (p, q, n): {best_config}")
